-- 00028: Seed del catálogo piloto (Maneiro, Mariño, Arismendi).
--
-- Municipios: FeatureServer ArcGIS 'División_Político_Territorial' (códigos INE).
-- Sectores: OpenStreetMap vía Overpass API (licencia ODbL), nombres tal cual
--   la fuente; se depuran con el uso real del piloto.
-- UUIDs determinísticos (uuid5) para que el seed sea idempotente.

on conflict (id) do nothing;

-- Sectores por municipio (nombre único dentro del municipio).
on conflict (municipality_id, name) do nothing;
